css:
:scope{--ink:var(--os-color-text);--teal:#0F5457;--cream:var(--os-color-background);--rose:var(--os-color-accent);--rose-soft:#E8A3BE;--gold:#C9A04E;--serif:'Cormorant Garamond', Georgia, serif;--sans:'Jost', system-ui, sans-serif;--script:'Pinyon Script', cursive}
:scope{color:var(--ink);font-family:var(--sans);font-weight:300;font-size:18px;line-height:1.75}
@media (max-width:767px){:scope{font-size:17px}}
:where(h1,h2,h3,h4,h5,h6){color:inherit;font-family:inherit;font-weight:bold;font-style:inherit;letter-spacing:normal;text-transform:none;line-height:inherit;text-wrap:wrap}
:where(h1){font-size:2em}:where(h2){font-size:1.5em}:where(h3){font-size:1.17em}:where(h4){font-size:1em}:where(h5){font-size:.83em}:where(h6){font-size:.67em}
:where(.os-ci){display:inline-block;max-width:100%;vertical-align:middle;aspect-ratio:auto}
.os-ci>picture{display:contents}
.os-ci img{display:block;width:100%;height:100%;object-fit:inherit;object-position:inherit;border-radius:inherit}
*{box-sizing:border-box}
a{color:var(--teal)}
a:hover{color:var(--rose)}
h1{font-family:var(--serif);font-weight:300;margin:0;line-height:1.08;color:var(--teal)}
p{margin:0}
.gold-text{background:linear-gradient(100deg,#B8862E 0%,#F6E2A8 38%,#D8B160 60%,#9E7425 100%);-webkit-background-clip:text;background-clip:text;color:transparent}
.eyebrow{font-size:14px;letter-spacing:.34em;text-transform:uppercase;color:var(--rose);font-weight:400}
.script{font-family:var(--script);color:var(--rose);line-height:1.1}
.temple{position:relative;overflow:hidden;color:#F3EBDD;background:radial-gradient(ellipse 45% 40% at 50% 70%,rgba(240,200,110,.35),rgba(240,200,110,0) 70%),radial-gradient(ellipse 30% 30% at 15% 30%,rgba(163,48,95,.3),rgba(163,48,95,0) 70%),radial-gradient(ellipse 30% 30% at 85% 25%,rgba(43,169,166,.22),rgba(43,169,166,0) 70%),linear-gradient(180deg,#071F22,#0B2B2E 60%,#12393B)}
.site-header{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:16px;max-width:1240px;margin:0 auto;padding:24px}
.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:#F6E2A8;font-family:var(--serif);font-size:26px;font-weight:500;letter-spacing:.06em}
.site-nav{display:flex;flex-wrap:wrap;align-items:center;gap:8px 26px;font-size:15px;letter-spacing:.14em;text-transform:uppercase}
.site-nav a{color:#E9F2F1;text-decoration:none;padding:12px 0}
.site-nav a.current{color:#F6E2A8;border-bottom:1px solid var(--gold)}
.site-nav a.nav-book{border:1px solid var(--gold);color:#F6E2A8;padding:12px 22px;border-radius:999px}
.fade{height:100px;background:linear-gradient(180deg,rgba(251,248,241,0),var(--cream))}
.page-hero{max-width:860px;margin:0 auto;padding:60px 24px 110px;text-align:center;display:flex;flex-direction:column;gap:18px;align-items:center}
.page-hero h1{font-size:clamp(44px,6vw,86px);line-height:1.04}
.page-hero .script{font-size:clamp(34px,4vw,44px);color:var(--rose-soft)}
.page-hero .eyebrow{color:var(--rose-soft)}
.page-hero .note{font-size:15px;letter-spacing:.12em;text-transform:uppercase;color:#D6E6E4}
section{padding:100px 0}
@media (max-width:767px){section{padding:72px 0}}
